import type { IQuotaProvider, QuotaConfig, ProviderResult, TestConnectionResult, AccountConfigItem } from '../core/types.ts'
import { fetchWithProxy } from '../core/fetch.ts'

interface DeepSeekBalanceResponse {
  is_available?: boolean
  balance_infos?: Array<{
    currency?: string
    total_balance?: string | number
    granted_balance?: string | number
    topped_up_balance?: string | number
  }>
}

export class DeepSeekProvider implements IQuotaProvider {
  name = 'deepseek'
  category = 'domestic_llm' as const

  private resolveKey(config: QuotaConfig, accountConfig?: AccountConfigItem): { apiKey: string; baseUrl: string } {
    let apiKey = (accountConfig && accountConfig.apiKey !== undefined
      ? accountConfig.apiKey
      : (config.deepseek?.apiKey || process.env.DEEPSEEK_API_KEY || '')).trim()
    apiKey = apiKey.replace(/^Bearer\s+/i, '')
    const baseUrl = (accountConfig?.baseUrl || config.deepseek?.baseUrl || 'https://api.deepseek.com').replace(/\/+$/, '')
    return { apiKey, baseUrl }
  }

  async testConnection(config: QuotaConfig, accountConfig?: AccountConfigItem): Promise<TestConnectionResult> {
    const start = Date.now()
    const { apiKey, baseUrl } = this.resolveKey(config, accountConfig)
    if (!apiKey) {
      return {
        ok: false,
        provider: 'deepseek',
        message: '未配置 DeepSeek API Key。请在「设置」中填入 Key',
      }
    }

    try {
      const url = `${baseUrl}/user/balance`
      const res = await fetchWithProxy(url, {
        headers: {
          Authorization: `Bearer ${apiKey}`,
          Accept: 'application/json',
        },
      }, config.httpProxy, 10000, config.proxyMode)

      const latencyMs = Date.now() - start
      if (!res.ok) {
        let detail = `HTTP ${res.status}`
        try {
          const errData = await res.json() as any
          if (errData?.error?.message) {
            detail = errData.error.message
          } else if (res.status === 401) {
            detail = 'API Key 无效或未授权 (HTTP 401)'
          } else if (res.status === 403) {
            detail = '无访问权限或 IP 受限 (HTTP 403)'
          }
        } catch {
          if (res.status === 401) detail = 'API Key 无效或已过期 (HTTP 401)'
        }
        return {
          ok: false,
          provider: 'deepseek',
          latencyMs,
          message: `验证失败: ${detail}`,
        }
      }

      const data = await res.json() as DeepSeekBalanceResponse
      const info = data.balance_infos?.[0]
      const total = info?.total_balance ?? '0.00'
      const currency = info?.currency || 'CNY'
      return {
        ok: true,
        provider: 'deepseek',
        latencyMs,
        account: `余额: ¥${total} ${currency}`,
        message: `连接成功 (延迟: ${latencyMs}ms, 余额: ¥${total})`,
      }
    } catch (err: any) {
      return {
        ok: false,
        provider: 'deepseek',
        latencyMs: Date.now() - start,
        message: `网络请求异常: ${err.message}`,
      }
    }
  }

  async fetchCard(config: QuotaConfig, accountConfig?: AccountConfigItem): Promise<ProviderResult> {
    const cardId = accountConfig?.id || 'deepseek'
    const cardName = accountConfig?.name || config.customNames?.deepseek || config.deepseek?.name || 'DeepSeek'
    const { apiKey, baseUrl } = this.resolveKey(config, accountConfig)

    if (!apiKey) {
      return {
        card: {
          id: cardId,
          name: cardName,
          provider: 'deepseek',
          category: this.category,
          status: 'disabled',
          error: '未配置 API Key。请在「设置」中填入 DeepSeek API Key',
          groups: [],
          lastUpdated: Date.now(),
        },
      }
    }

    try {
      const url = `${baseUrl}/user/balance`
      const res = await fetchWithProxy(url, {
        headers: {
          Authorization: `Bearer ${apiKey}`,
          Accept: 'application/json',
        },
      }, config.httpProxy, 15000, config.proxyMode)

      if (!res.ok) {
        throw new Error(`API 错误 (${res.status})`)
      }

      const data = await res.json() as DeepSeekBalanceResponse
      const info = data.balance_infos?.[0]
      const isAvailable = data.is_available !== false

      const totalBalance = typeof info?.total_balance === 'string' ? parseFloat(info.total_balance) : (info?.total_balance ?? 0)
      const grantedBalance = typeof info?.granted_balance === 'string' ? parseFloat(info.granted_balance) : (info?.granted_balance ?? 0)
      const toppedUpBalance = typeof info?.topped_up_balance === 'string' ? parseFloat(info.topped_up_balance) : (info?.topped_up_balance ?? 0)
      const currency = (info?.currency || 'CNY').toUpperCase() as 'CNY' | 'USD'

      const totalAmount = Math.max(0, totalBalance)
      const isLow = totalAmount <= 5
      // `error` is reserved for an unavailable account (401/403/network), never for a
      // zero balance — that is a warning the alarm layer reports as "余额不足".
      const status = !isAvailable ? 'error' : (isLow ? 'warn' : 'ok')
      const remPercent = totalAmount <= 0 ? 0 : (totalAmount < 5 ? 15 : (totalAmount < 20 ? 40 : 100))
      const usedPercent = 100 - remPercent

      const subtitle = `总额: ¥${totalAmount.toFixed(2)} (充值 ¥${toppedUpBalance.toFixed(2)} + 赠送 ¥${grantedBalance.toFixed(2)})`

      return {
        card: {
          id: cardId,
          name: cardName,
          provider: 'deepseek',
          category: this.category,
          status,
          plan: 'DeepSeek 官方平台',
          account: `¥${totalAmount.toFixed(2)} ${currency}`,
          balance: {
            currency,
            total: totalAmount,
            remaining: totalAmount,
            grantedBalance,
            toppedUpBalance,
          },
          groups: [
            {
              id: 'deepseek-balance-group',
              title: '账户余额',
              hasInfoIcon: true,
              poolType: 'general',
              windows: [
                {
                  id: 'deepseek-balance',
                  label: '可用余额',
                  subtitle: `充值: ¥${toppedUpBalance.toFixed(2)} · 赠送: ¥${grantedBalance.toFixed(2)}`,
                  usedPercent,
                  remainingPercent: remPercent,
                  barType: 'balance',
                  // Displayed as an amount everywhere; the percentage above only drives
                  // colour banding and is never rendered as a quota number.
                  amountText: `¥${totalAmount.toFixed(2)}`,
                  status: totalAmount <= 0 ? 'exhausted' : 'active',
                },
              ],
            },
          ],
          lastUpdated: Date.now(),
          sourceProvenance: {
            endpoint: url,
            method: 'user-balance',
            timestamp: Date.now(),
            host: 'api.deepseek.com',
          },
        },
      }
    } catch (err: any) {
      return {
        card: {
          id: cardId,
          name: cardName,
          provider: 'deepseek',
          category: this.category,
          status: 'error',
          error: err.message,
          groups: [],
          lastUpdated: Date.now(),
        },
      }
    }
  }
}
